package ai.eva.android.probe;
import android.accessibilityservice.*;import android.view.accessibility.*;import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.io.*;
/** User-enabled UI automation. All actions run on the accessibility main thread. */
public class PhoneAccessibility extends AccessibilityService {
 static volatile PhoneAccessibility live;static volatile boolean armed;static volatile long generation;
 static final ExecutorService imageWorker=Executors.newSingleThreadExecutor();int visited;long scanDeadline;
 final Map<String,AccessibilityNodeInfo> nodes=new HashMap<>();long observedAt;String snapshot="",snapshotPackage="";int snapshotWindow=-1;
 protected void onServiceConnected(){live=this;PhoneTaskService.restore(this);}
 String foregroundPackage="";int foregroundWindow=-1;volatile long windowRevision,observedRevision;
 public void onAccessibilityEvent(AccessibilityEvent e){if(e.getEventType()==AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED&&e.getPackageName()!=null){String pkg=e.getPackageName().toString();if(!pkg.equals(foregroundPackage)||foregroundWindow!=e.getWindowId()){foregroundPackage=pkg;foregroundWindow=e.getWindowId();windowRevision++;}}}
 AccessibilityNodeInfo readableRoot(){AccessibilityNodeInfo root=getRootInActiveWindow();if(root!=null)return root;java.util.List<AccessibilityWindowInfo> windows=getWindows();if(windows!=null)for(AccessibilityWindowInfo w:windows){if(w.getType()==AccessibilityWindowInfo.TYPE_APPLICATION&&(w.isActive()||w.isFocused())){root=w.getRoot();if(root!=null)return root;}}return null;}
 void observeAsync(CompletableFuture<JSONObject> result,boolean image,int attempt,long epoch){try{guard();if(epoch!=generation)throw new IOException("操作已取消");JSONObject state=observe();if(state.getJSONArray("nodes").length()==0&&attempt<3){new Handler(getMainLooper()).postDelayed(()->observeAsync(result,image,attempt+1,epoch),200);return;}int labels=0;JSONArray rows=state.getJSONArray("nodes");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.optString("text").isEmpty()||!row.optString("description").isEmpty())labels++;}if(image||labels<3){CompletableFuture<JSONObject> shot=new CompletableFuture<>();shot.whenComplete((picture,error)->{try{if(epoch!=generation||observedRevision!=windowRevision){result.completeExceptionally(new IOException("操作已取消"));return;}if(error!=null){state.put("screenshotError",String.valueOf(error.getMessage()));state.put("instruction","页面树不足且截图不可用。请报告具体原因，不要声称已识别联系人。");}else{for(Iterator<String> keys=picture.keys();keys.hasNext();){String key=keys.next();state.put(key,picture.get(key));}state.put("recognition","accessibility+vision");state.put("instruction","结合截图识别；缺少可点击节点时使用当前 snapshot 和物理屏幕坐标 gesture。不要仅因 nodes 为空判断页面无法操作。");}result.complete(state);}catch(Exception e){result.completeExceptionally(e);}});screenshot(shot);}else result.complete(state);}catch(Exception e){result.completeExceptionally(e);}}

 public void onInterrupt(){clearNodes();}
 public void onDestroy(){if(live==this){PhoneTaskReport.close();stopControl();clearNodes();live=null;PhoneTaskService.reason(this,"无障碍连接已断开，等待系统重连");}super.onDestroy();}
 static void stopControl(){armed=false;generation++;PhoneShell.cancel();PhoneAccessibility s=live;if(s!=null)new Handler(s.getMainLooper()).post(s::clearNodes);}
 void clearNodes(){for(AccessibilityNodeInfo n:nodes.values())n.recycle();nodes.clear();snapshot="";}
 void guard()throws Exception{if(!armed)throw new IOException("手机控制已停止，请在 Eva 的手机控制页开启");if(((KeyguardManager)getSystemService(KEYGUARD_SERVICE)).isKeyguardLocked())throw new IOException("手机已锁定，请解锁后继续");}
 JSONObject observe()throws Exception{guard();clearNodes();AccessibilityNodeInfo root=readableRoot();observedAt=SystemClock.elapsedRealtime();snapshot=UUID.randomUUID().toString();observedRevision=windowRevision;snapshotWindow=root==null?-1:root.getWindowId();snapshotPackage=root==null?foregroundPackage:String.valueOf(root.getPackageName());JSONArray list=new JSONArray();visited=0;scanDeadline=SystemClock.elapsedRealtime()+180;if(root!=null){walk(root,list,0);root.recycle();}android.util.DisplayMetrics dm=getResources().getDisplayMetrics();return new JSONObject().put("snapshot",snapshot).put("package",snapshotPackage).put("width",dm.widthPixels).put("height",dm.heightPixels).put("nodes",list).put("truncated",list.length()>=500||visited>=1500||SystemClock.elapsedRealtime()>scanDeadline).put("recognition",list.length()==0?"visual-fallback-needed":"accessibility").put("instruction","操作后重新 observe 验证。未找到目标时可 screenshot 检查，或使用 App 搜索入口，不能据此断言目标不存在。");}
 void walk(AccessibilityNodeInfo n,JSONArray out,int depth)throws Exception{if(depth>30||out.length()>=500||++visited>1500||SystemClock.elapsedRealtime()>scanDeadline)return;if(n.isVisibleToUser()){String id="n"+out.length();Rect b=new Rect();n.getBoundsInScreen(b);JSONObject row=new JSONObject().put("id",id).put("class",String.valueOf(n.getClassName())).put("text",n.isPassword()?"[password]":clip(n.getText())).put("description",n.isPassword()?"":clip(n.getContentDescription())).put("bounds",new JSONArray(new int[]{b.left,b.top,b.right,b.bottom})).put("resourceId",n.getViewIdResourceName()).put("selected",n.isSelected()).put("checked",n.isChecked()).put("hint",n.isPassword()?"":clip(n.getHintText())).put("clickable",n.isClickable()).put("editable",n.isEditable()).put("scrollable",n.isScrollable()).put("enabled",n.isEnabled());out.put(row);nodes.put(id,AccessibilityNodeInfo.obtain(n));}for(int i=0;i<n.getChildCount()&&out.length()<500&&visited<1500&&SystemClock.elapsedRealtime()<=scanDeadline;i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null){walk(child,out,depth+1);child.recycle();}}}
 String clip(CharSequence s){if(s==null)return "";String t=s.toString();return t.length()>500?t.substring(0,500):t;}
 void validSnapshot(JSONObject args)throws Exception{if(SystemClock.elapsedRealtime()-observedAt>15000||snapshot.isEmpty()||!snapshot.equals(args.optString("snapshot")))throw new IOException("页面快照已失效，请先 observe");AccessibilityNodeInfo root=readableRoot();if(snapshotWindow==-1){if(observedRevision!=windowRevision)throw new IOException("前台窗口已变化，请重新 observe");if(root!=null)root.recycle();return;}if(root==null)throw new IOException("窗口正在切换，请重新 observe 获取截图与快照");boolean match=root.getWindowId()==snapshotWindow&&snapshotPackage.equals(String.valueOf(root.getPackageName()));root.recycle();if(!match)throw new IOException("前台 App 已变化，请重新 observe");}
 JSONObject action(String action,JSONObject a)throws Exception{guard();if(action.equals("observe"))return observe();if(action.equals("back")||action.equals("home")){validSnapshot(a);boolean ok=performGlobalAction(action.equals("back")?GLOBAL_ACTION_BACK:GLOBAL_ACTION_HOME);clearNodes();return new JSONObject().put("dispatched",ok);}validSnapshot(a);AccessibilityNodeInfo node=nodes.get(a.optString("node"));if(node==null||!node.refresh()||!node.isVisibleToUser())throw new IOException("控件不可用，请重新 observe");if(node.isPassword())throw new IOException("密码框需用户手动输入");boolean ok=false;if(action.equals("click"))ok=actOnAncestor(node,AccessibilityNodeInfo.ACTION_CLICK);else if(action.equals("input")){String value=a.getString("text");if(value.length()>10000)throw new IOException("输入过长");Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);ok=node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b);}else if(action.equals("scroll"))ok=actOnAncestor(node,(a.optString("direction").equals("backward")||a.optString("direction").equals("up"))?AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD:AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);else throw new IOException("未知操作");clearNodes();return new JSONObject().put("dispatched",ok).put("instruction","必须重新 observe 验证结果");}
 boolean actOnAncestor(AccessibilityNodeInfo start,int action){AccessibilityNodeInfo cursor=AccessibilityNodeInfo.obtain(start);try{for(int depth=0;cursor!=null&&depth<6;depth++){boolean eligible=action==AccessibilityNodeInfo.ACTION_CLICK?cursor.isClickable():cursor.isScrollable();if(cursor.isEnabled()&&eligible&&cursor.performAction(action))return true;AccessibilityNodeInfo parent=cursor.getParent();cursor.recycle();cursor=parent;}return false;}finally{if(cursor!=null)cursor.recycle();}}
 void gesture(JSONObject a,CompletableFuture<JSONObject> result){try{guard();validSnapshot(a);android.util.DisplayMetrics dm=getResources().getDisplayMetrics();float x=(float)a.getDouble("x"),y=(float)a.getDouble("y"),ex=(float)a.optDouble("endX",x),ey=(float)a.optDouble("endY",y);if(!Float.isFinite(x)||!Float.isFinite(y)||!Float.isFinite(ex)||!Float.isFinite(ey)||Math.min(x,ex)<0||Math.min(y,ey)<0||Math.max(x,ex)>=dm.widthPixels||Math.max(y,ey)>=dm.heightPixels)throw new IOException("坐标超出屏幕");Path path=new Path();path.moveTo(x,y);path.lineTo(ex,ey);long duration=Math.max(80,Math.min(1500,a.optLong("durationMs",250)));boolean started=dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,duration)).build(),new GestureResultCallback(){public void onCompleted(GestureDescription d){try{result.complete(new JSONObject().put("dispatched",true));}catch(Exception e){result.completeExceptionally(e);}}public void onCancelled(GestureDescription d){result.completeExceptionally(new IOException("手势被取消"));}},null);clearNodes();if(!started)throw new IOException("系统拒绝手势");}catch(Exception e){result.completeExceptionally(e);}}
 void screenshot(CompletableFuture<JSONObject> result){try{guard();final long epoch=generation;if(Build.VERSION.SDK_INT<30)throw new IOException("当前系统不支持无障碍截图");takeScreenshot(0,getMainExecutor(),new TakeScreenshotCallback(){public void onSuccess(ScreenshotResult r){imageWorker.execute(()->{Bitmap hardware=null,copy=null;try{guard();if(epoch!=generation)throw new IOException("操作已取消");hardware=Bitmap.wrapHardwareBuffer(r.getHardwareBuffer(),r.getColorSpace());if(hardware==null)throw new IOException("截图为空");copy=hardware.copy(Bitmap.Config.ARGB_8888,false);int sw=copy.getWidth(),sh=copy.getHeight();if(Math.max(sw,sh)>1920){float ratio=1920f/Math.max(sw,sh);Bitmap small=Bitmap.createScaledBitmap(copy,Math.round(sw*ratio),Math.round(sh*ratio),true);copy.recycle();copy=small;}ByteArrayOutputStream out=new ByteArrayOutputStream();int width=copy.getWidth(),height=copy.getHeight();copy.compress(Bitmap.CompressFormat.JPEG,75,out);guard();if(epoch!=generation)throw new IOException("操作已取消");result.complete(new JSONObject().put("imageWidth",width).put("imageHeight",height).put("screenWidth",sw).put("screenHeight",sh).put("imageUrl","data:image/jpeg;base64,"+android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP)));}catch(Exception e){result.completeExceptionally(e);}finally{if(copy!=null)copy.recycle();if(hardware!=null)hardware.recycle();r.getHardwareBuffer().close();}});}public void onFailure(int code){result.completeExceptionally(new IOException("截图失败，系统错误码 "+code+"；若页面受保护不可绕过，请用户手动处理"));}});}catch(Exception e){result.completeExceptionally(e);}}
}
